fn main() {
    let args: Vec<String> = std::env::args_os()
        .skip(1)
        .map(|a| a.to_string_lossy().into_owned())
        .collect();
    let code = match cli::parse(&args) {
        Ok(cli::Parsed::Format(m)) => format_cmd::run_format(&m),
        Ok(cli::Parsed::ToYaml(m)) => json::run_to_yaml(&m),
        Ok(cli::Parsed::GitFilter(name, m)) => gitfilter::run(name, &m),
        Err(cli::CliExit::Stdout(s)) => {
            let mut out = std::io::stdout();
            let _ = out.write_all(s.as_bytes());
            let _ = out.flush();
            0
        }
        Err(cli::CliExit::Stderr(s, code)) => {
            let mut err = std::io::stderr();
            let _ = err.write_all(s.as_bytes());
            let _ = err.flush();
            code
        }
    };
    std::process::exit(code);
}
// Formatting options shared by the formatters.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Wrap {
    None,
    Paragraph,
    Sentence(Option<usize>),
    Column(usize),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TableWidths {
    Fit,
    Preserve,
}

pub fn parse_wrap(s: &str) -> Option<Wrap> {
    match s {
        "none" => Some(Wrap::None),
        "paragraph" => Some(Wrap::Paragraph),
        "sentence" => Some(Wrap::Sentence(None)),
        _ => {
            if let Some(rest) = s.strip_prefix("sentence:") {
                match rest.parse::<usize>() {
                    Ok(n) if n > 0 => Some(Wrap::Sentence(Some(n))),
                    _ => None,
                }
            } else {
                match s.parse::<usize>() {
                    Ok(n) if n > 0 => Some(Wrap::Column(n)),
                    _ => None,
                }
            }
        }
    }
}

