// Markdown formatting.

pub mod block;
pub mod format;
pub mod inline;
pub mod table;
pub mod width;
pub mod wrap;

use crate::format_cmd::Diagnostic;
use crate::options::{Options, TableWidths, Wrap};
use block::Block;

fn split_lines(text: &str) -> Vec<String> {
    let body = text.strip_suffix('\n').unwrap_or(text);
    if body.is_empty() && text.is_empty() {
        return Vec::new();
    }
    body.split('\n').map(|s| s.to_string()).collect()
}

/// Option words and scope of an option-only directive comment
/// (`<!-- fmt: wrap=40 scope=from-here -->`); the default scope is the file.
pub fn option_directive(line: &str) -> Option<(Vec<String>, &'static str)> {
    let d = directive_of(line)?;
    let mut words = Vec::new();
    // `markdown` options apply to the next block unless scoped otherwise.
    let (d, mut scope) = match d.strip_prefix("markdown") {
        Some(rest) if rest.is_empty() || rest.starts_with(char::is_whitespace) => (rest.to_string(), "next"),
        _ => (d, "file"),
    };
    for w in d.split_whitespace() {
        match w.strip_prefix("scope=") {
            Some("next") => scope = "next",
            Some("from-here") => scope = "from-here",
            Some(_) => scope = "file",
            None => words.push(w.to_string()),
        }
    }
    let is_option = |w: &String| w.contains('=') || w == "canonical";
    if words.is_empty() || !words.iter().all(is_option) {
        return None;
    }
    Some((words, scope))
}

/// Directive comment lines outside containers, in document order, as (0-based
/// line, line text). `line0` is the line of the first block.
fn directive_lines(blocks: &[Block], line0: usize, out: &mut Vec<(usize, String)>) {
    let mut line = line0;
    for b in blocks {
        match b {
            Block::Comment(ls) | Block::Para(ls) | Block::Raw(ls) => {
                for (k, l) in ls.iter().enumerate() {
                    if directive_of(l).is_some() {
                        out.push((line + k, l.clone()));
                    }
                }
            }
            Block::Div { inner, .. } => directive_lines(inner, line + 1, out),
            _ => {}
        }
        line += block::line_count(b);
    }
}

/// Check directive comments in document order, up to a `skip file` directive.
/// The block after a `skip` directive is checked too, `fmt: off` regions are not.
/// `lines` are the source lines from `line0` on.
fn check_directives(blocks: &[Block], lines: &[String], line0: usize) -> Result<bool, Diagnostic> {
    use crate::yaml::directive::{check_markdown, check_option_word, check_toggle, DirKind};
    let mut found = Vec::new();
    for b in blocks {
        match b {
            Block::Verbatim(ls) if directive_of(&ls[0]).is_some_and(|d| d.starts_with("skip")) => {
                directive_lines(&block::parse_blocks(&ls[1..]), 0, &mut found);
            }
            _ => directive_lines(std::slice::from_ref(b), 0, &mut found),
        }
    }
    // Locate the lines in the source, in order.
    let mut next = 0;
    let mut located = Vec::new();
    for (_, l) in found {
        if let Some(k) = lines[next..].iter().position(|s| *s == l) {
            located.push((line0 + next + k, l));
            next += k + 1;
        }
    }
    for (n, l) in located {
        let Some(d) = directive_of(&l) else { continue };
        let col = l[..l.find("fmt:").unwrap_or(0)].chars().count() + 1;
        let words: Vec<&str> = d.split_whitespace().collect();
        let r = match words.first().copied() {
            None => Err("invalid fmt directive: empty".to_string()),
            Some("skip" | "off" | "on") => match check_toggle(&words) {
                Ok(DirKind::SkipFile) => return Ok(true),
                r => r.map(|_| ()),
            },
            Some("markdown") => check_markdown(&words[1..]),
            Some(w) if w.contains('=') || w == "canonical" => words.iter().try_for_each(|w| check_option_word(w)),
            Some(_) => Err(format!("invalid fmt directive: {}", d)),
        };
        r.map_err(|m| Diagnostic::new(n + 1, col, m))?;
    }
    Ok(false)
}

/// Check the directives of a document unless its front matter is unreadable (the
/// document is then kept as written).
fn check_text_directives(all: &[String]) -> Result<(), Diagnostic> {
    let fm_end = front_matter_end(all);
    let fm_ok = fm_end.is_none_or(|end| end <= 1 || crate::yaml::parser::Parser::new(&format!("{}\n", all[1..end].join("\n"))).parse_stream().is_ok());
    if fm_ok {
        let body_start = fm_end.map_or(0, |e| e + 1);
        check_directives(&parse_with_directives(&all[body_start..], None), &all[body_start..], body_start)?;
    }
    Ok(())
}

fn directive_of(line: &str) -> Option<String> {
    let t = line.trim();
    let inner = t.strip_prefix("<!--")?.strip_suffix("-->")?.trim();
    let d = inner.strip_prefix("fmt:")?;
    Some(d.trim().to_string())
}

/// Find the end of YAML front matter starting at line 0.
fn front_matter_end(lines: &[String]) -> Option<usize> {
    if lines.is_empty() || lines[0].trim_end() != "---" {
        return None;
    }
    for (i, l) in lines.iter().enumerate().skip(1) {
        let t = l.trim_end();
        if t == "---" || t == "..." {
            return Some(i);
        }
    }
    None
}

/// Read editor_options.markdown settings from front matter YAML.
fn apply_front_matter_options(yaml: &str, opts: &mut Options) {
    let p = crate::yaml::parser::Parser::new(yaml);
    let src = yaml;
    let stream = match p.parse_stream() {
        Ok(s) => s,
        Err(_) => return,
    };
    // Options written after a structurally recovered line are not read.
    let recovered = crate::yaml::parser::last_struct_recovery();
    let root = match stream.docs.first().and_then(|d| d.root.as_ref()) {
        Some(r) => r,
        None => return,
    };
    let find = |n: &crate::yaml::parser::Node, key: &str| -> Option<crate::yaml::parser::Node> {
        if let crate::yaml::parser::Kind::Map(entries) = &n.kind {
            for e in entries {
                let k = &src[e.start..e.key_end];
                let k = k.trim_matches(|c| c == '"' || c == '\'');
                if k == key {
                    return Some(e.value.clone());
                }
            }
        }
        if let crate::yaml::parser::Kind::FlowMap(entries) = &n.kind {
            for e in entries {
                if let Some(k) = &e.key {
                    if let crate::yaml::parser::Kind::Scalar(sc) = &k.kind {
                        if sc.value == key {
                            return e.value.clone();
                        }
                    }
                }
            }
        }
        None
    };
    let md = match find(root, "editor_options").and_then(|eo| find(&eo, "markdown")) {
        Some(m) => Some(m),
        None => find(root, "editor").and_then(|e| find(&e, "markdown")),
    };
    let md = match md {
        Some(m) if recovered.is_none_or(|l| m.line < l) => m,
        _ => return,
    };
    let scalar = |n: Option<crate::yaml::parser::Node>| -> Option<String> {
        match n?.kind {
            crate::yaml::parser::Kind::Scalar(sc) => Some(sc.value),
            _ => None,
        }
    };
    if let Some(w) = scalar(find(&md, "wrap")) {
        if let Some(w) = crate::options::parse_wrap(&w) {
            opts.wrap = w;
        }
    }
    if let Some(c) = scalar(find(&md, "canonical")) {
        match c.as_str() {
            "true" | "yes" | "1" => opts.canonical = true,
            "false" | "no" | "0" => opts.canonical = false,
            _ => {}
        }
    }
    if let Some(f) = scalar(find(&md, "footnotes")) {
        match f.as_str() {
            "preserve" | "none" | "false" | "no" | "0" => opts.preserve_footnotes = true,
            "wrap" | "format" | "true" | "yes" | "1" => {}
            _ => {}
        }
    }
    if let Some(t) = scalar(find(&md, "table-widths")) {
        match t.as_str() {
            "fit" => opts.table_widths = TableWidths::Fit,
            "preserve" => opts.table_widths = TableWidths::Preserve,
            _ => {}
        }
    }
}

/// Parse blocks applying top-level preserve directives.
fn parse_with_directives(lines: &[String], base: Option<usize>) -> Vec<Block> {
    // Split at fmt: off/on regions and fmt: skip targets.
    let mut out: Vec<Block> = Vec::new();
    let mut seg_start = 0;
    let mut i = 0;
    let n = lines.len();
    let mut in_fence: Option<(char, usize)> = None;
    while i < n {
        let l = &lines[i];
        if let Some((ch, len)) = in_fence {
            let t = l.trim();
            if block::indent_of(l) <= 3 && t.chars().take_while(|&c| c == ch).count() >= len && t.chars().all(|c| c == ch) {
                in_fence = None;
            }
            i += 1;
            continue;
        }
        if let Some(f) = block::fence_open(l) {
            in_fence = Some((f.ch, f.len));
            i += 1;
            continue;
        }
        if block::indent_of(l) == 0 {
            if let Some(d) = directive_of(l) {
                if d == "off" || d == "off scope=from-here" {
                    out.extend(block::parse_blocks_at(&lines[seg_start..i], base.map(|b| b + seg_start)));
                    let s = i;
                    let mut j = i + 1;
                    while j < n {
                        if directive_of(&lines[j]).as_deref() == Some("on") {
                            break;
                        }
                        j += 1;
                    }
                    let e = if j < n { j + 1 } else { n };
                    out.push(Block::Verbatim(lines[s..e].to_vec()));
                    i = e;
                    seg_start = e;
                    continue;
                }
                if d == "skip" || d == "skip scope=next" {
                    out.extend(block::parse_blocks_at(&lines[seg_start..i], base.map(|b| b + seg_start)));
                    let s = i;
                    let mut j = i + 1;
                    while j < n && block::is_blank(&lines[j]) {
                        j += 1;
                    }
                    // Next block extent: parse from j and take the first block's line span.
                    let rest = &lines[j..];
                    let span = first_block_span(rest);
                    let e = (j + span).min(n);
                    out.push(Block::Verbatim(lines[s..e].to_vec()));
                    i = e;
                    seg_start = e;
                    continue;
                }
            }
        }
        i += 1;
    }
    out.extend(block::parse_blocks_at(&lines[seg_start..n], base.map(|b| b + seg_start)));
    out
}

/// Number of lines spanned by the first block of `lines`.
fn first_block_span(lines: &[String]) -> usize {
    if lines.is_empty() {
        return 0;
    }
    for k in 1..=lines.len() {
        let bs = block::parse_blocks(&lines[..k]);
        let full = block::parse_blocks(&lines[..lines.len().min(k + 1)]);
        if bs.len() == 1 && full.len() >= 2 {
            return k;
        }
        if full.len() == 1 && k == lines.len() {
            return k;
        }
    }
    lines.len()
}

fn has_skip_file(lines: &[String]) -> bool {
    let mut in_fence: Option<(char, usize)> = None;
    for l in lines {
        if let Some((ch, len)) = in_fence {
            let t = l.trim();
            if t.chars().take_while(|&c| c == ch).count() >= len && t.chars().all(|c| c == ch) {
                in_fence = None;
            }
            continue;
        }
        if let Some(f) = block::fence_open(l) {
            in_fence = Some((f.ch, f.len));
            continue;
        }
        if let Some(d) = directive_of(l) {
            if d == "skip file" || d == "skip scope=file" {
                return true;
            }
        }
    }
    false
}

fn wrap_total(w: Wrap) -> usize {
    match w {
        Wrap::Column(n) => n,
        Wrap::Sentence(Some(n)) => n,
        _ => usize::MAX / 4,
    }
}

thread_local! {
    /// The first invalid directive found in embedded Markdown.
    static FRAGMENT_ERROR: std::cell::RefCell<Option<Diagnostic>> = const { std::cell::RefCell::new(None) };
}

/// Take the directive error recorded while formatting embedded Markdown.
pub fn take_fragment_error() -> Option<Diagnostic> {
    FRAGMENT_ERROR.with(|e| e.borrow_mut().take())
}

/// Format a Markdown fragment (no final newline handling); returns lines.
/// Invalid directives are recorded with positions offset by `origin`
/// (0-based line, column).
pub fn format_fragment(text: &str, opts: &Options, notes: &mut Vec<Diagnostic>, origin: (usize, usize)) -> Vec<String> {
    format::with_keep_trailing(true, || format_fragment_at(text, opts, notes, None, Some(origin)))
}

/// Format a fragment whose first line is absolute line `line_base` (for notes).
pub fn format_fragment_at(text: &str, opts: &Options, notes: &mut Vec<Diagnostic>, line_base: Option<usize>, origin: Option<(usize, usize)>) -> Vec<String> {
    let lines = split_lines(text);
    if let Some((l0, c0)) = origin {
        if let Err(mut d) = check_text_directives(&lines) {
            d.line += l0;
            d.col += c0;
            FRAGMENT_ERROR.with(|e| {
                e.borrow_mut().get_or_insert(d);
            });
        }
    }
    if has_skip_file(&lines) {
        return lines;
    }
    let mut opts = opts.clone();
    let mut out: Vec<String> = Vec::new();
    let mut body_start = 0;
    if let Some(end) = front_matter_end(&lines) {
        let yaml_src = if end > 1 { format!("{}\n", lines[1..end].join("\n")) } else { String::new() };
        if !yaml_src.is_empty() && crate::yaml::parser::Parser::new(&yaml_src).parse_stream().is_err() {
            return lines;
        }
        if !opts.ignore_document_options {
            apply_front_matter_options(&yaml_src, &mut opts);
        }
        let formatted = crate::yaml::format_yaml(&yaml_src, &opts).unwrap_or(yaml_src.clone());
        out.push(lines[0].trim_end().to_string());
        for l in formatted.strip_suffix('\n').unwrap_or(&formatted).split('\n') {
            if end > 1 {
                out.push(l.to_string());
            }
        }
        out.push(lines[end].trim_end().to_string());
        body_start = end + 1;
    }
    // File-scope option directives apply to the whole document.
    let blocks = parse_with_directives(&lines[body_start..], line_base.map(|b| b + body_start));
    let mut found = Vec::new();
    directive_lines(&blocks, 0, &mut found);
    for (_, l) in found {
        if let Some((words, "file")) = option_directive(&l) {
            crate::yaml::emit::apply_md_words(&mut opts, &words);
        }
    }
    let total = wrap_total(opts.wrap);
    let mut f = format::Fmt::new(opts, notes);
    f.emit_notes = line_base.is_some() && !f.opts.skip_embedded;
    out.extend(f.format_blocks(&blocks, 0, 0, total));
    out
}

pub fn format_markdown_file(text: &str, opts: &Options, notes: &mut Vec<Diagnostic>) -> Result<String, Diagnostic> {
    if text.is_empty() {
        return Ok(String::new());
    }
    check_text_directives(&split_lines(text))?;
    let lines = format::with_keep_trailing(false, || format_fragment_at(text, opts, notes, Some(0), None));
    let mut out = lines.join("\n");
    out.push('\n');
    Ok(out)
}
// JSON-family to YAML projection (`yamark to-yaml`).

use crate::cli::Matches;
use crate::format_cmd::Diagnostic;
use crate::options::Options;
use std::io::{Read, Write};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Dialect {
    Json,
    Jsonc,
    Json5,
}

#[derive(Debug, Clone)]
enum Value {
    Null,
    Bool(bool),
    /// Number spelled for YAML.
    Num(String),
    Str(String),
    Arr(Vec<Elem>, Vec<String>),
    Obj(Vec<(String, Elem)>, Vec<String>),
}

#[derive(Debug, Clone)]
struct Elem {
    /// Comments preceding the element.
    comments: Vec<String>,
    value: Value,
}

struct P<'a> {
    s: &'a [char],
    i: usize,
    d: Dialect,
    depth: usize,
    pending: Vec<String>,
    any_comment: bool,
}

type R<T> = Result<T, (usize, String)>;

impl<'a> P<'a> {
    fn peek(&self) -> Option<char> {
        self.s.get(self.i).copied()
    }

    fn skip_ws(&mut self) -> R<()> {
        loop {
            let c = match self.peek() {
                Some(c) => c,
                None => return Ok(()),
            };
            let is_ws = match self.d {
                Dialect::Json5 => c.is_whitespace() && c != '\u{85}' || c == '\u{feff}',
                _ => matches!(c, ' ' | '\t' | '\n' | '\r'),
            };
            if is_ws {
                self.i += 1;
                continue;
            }
            if c == '/' && self.d != Dialect::Json {
                match self.s.get(self.i + 1) {
                    Some('/') => {
                        let st = self.i + 2;
                        let mut j = st;
                        while j < self.s.len() && self.s[j] != '\n' {
                            j += 1;
                        }
                        let text: String = self.s[st..j].iter().collect();
                        self.pending.push(text.trim().to_string());
                        self.any_comment = true;
                        self.i = j;
                        continue;
                    }
                    Some('*') => {
                        let st = self.i + 2;
                        let mut j = st;
                        while j + 1 < self.s.len() && !(self.s[j] == '*' && self.s[j + 1] == '/') {
                            j += 1;
                        }
                        if j + 1 >= self.s.len() {
                            return Err((self.i, "Unterminated comment".into()));
                        }
                        let text: String = self.s[st..j].iter().collect();
                        for l in text.split('\n') {
                            let t = l.trim().trim_start_matches('*').trim();
                            if !t.is_empty() {
                                self.pending.push(t.to_string());
                            }
                        }
                        self.any_comment = true;
                        self.i = j + 2;
                        continue;
                    }
                    _ => {}
                }
            }
            return Ok(());
        }
    }

    fn take_comments(&mut self) -> Vec<String> {
        std::mem::take(&mut self.pending)
    }

    fn unexpected(&self) -> (usize, String) {
        match self.d {
            Dialect::Json5 => {
                let c = self.peek().unwrap_or(' ');
                let kind = match c {
                    ',' => "Comma",
                    ':' => "Colon",
                    '}' => "CloseBrace",
                    ']' => "CloseBracket",
                    '{' => "OpenBrace",
                    '[' => "OpenBracket",
                    _ => "Name",
                };
                if kind == "Name" {
                    let mut j = self.i;
                    while j < self.s.len() && (self.s[j].is_alphanumeric() || self.s[j] == '_' || self.s[j] == '$') {
                        j += 1;
                    }
                    let w: String = self.s[self.i..j.max(self.i + 1).min(self.s.len())].iter().collect();
                    return (self.i, format!("Unexpected token of type Name: \"{}\"", w));
                }
                (self.i, format!("Unexpected token of type {}: \"{}\"", kind, c))
            }
            _ => {
                if self.peek() == Some(',') {
                    return (self.i, "Unexpected comma".into());
                }
                (self.i, "Unexpected token".into())
            }
        }
    }

    fn value(&mut self) -> R<Value> {
        self.skip_ws()?;
        let c = match self.peek() {
            Some(c) => c,
            None => return Err((self.i, "expected a JSON value".into())),
        };
        match c {
            '{' => self.object(),
            '[' => self.array(),
            '"' => Ok(Value::Str(self.string('"')?)),
            '\'' if self.d == Dialect::Json5 => Ok(Value::Str(self.string('\'')?)),
            _ => self.literal(),
        }
    }

    fn enter(&mut self) -> R<()> {
        self.depth += 1;
        if self.depth > 256 {
            return Err((self.i, "nesting too deep".into()));
        }
        Ok(())
    }

    fn object(&mut self) -> R<Value> {
        let start = self.i;
        self.enter()?;
        self.i += 1;
        let mut members = Vec::new();
        loop {
            self.skip_ws()?;
            match self.peek() {
                None => {
                    return Err(match self.d {
                        Dialect::Json5 => (self.i, "Expecting '}' at end of object".into()),
                        _ => (start, "Unterminated object".into()),
                    })
                }
                Some('}') => {
                    self.i += 1;
                    break;
                }
                _ => {}
            }
            let comments = self.take_comments();
            let key = match self.peek() {
                Some('"') => self.string('"')?,
                Some('\'') if self.d == Dialect::Json5 => self.string('\'')?,
                Some(c) if self.d == Dialect::Json5 && (c.is_alphabetic() || c == '_' || c == '$' || c == '\\') => {
                    let st = self.i;
                    while self.i < self.s.len() && (self.s[self.i].is_alphanumeric() || self.s[self.i] == '_' || self.s[self.i] == '$') {
                        self.i += 1;
                    }
                    self.s[st..self.i].iter().collect()
                }
                _ => return Err(self.unexpected()),
            };
            self.skip_ws()?;
            if self.peek() != Some(':') {
                return Err(match self.d {
                    Dialect::Json5 => (self.i, "Expecting ':' delimiter".into()),
                    _ => (self.i, "Expected colon after the string or word in object property".into()),
                });
            }
            self.i += 1;
            let mut v = self.value()?;
            let _ = &mut v;
            members.push((key, Elem { comments, value: v }));
            self.skip_ws()?;
            match self.peek() {
                Some(',') => {
                    let comma = self.i;
                    self.i += 1;
                    self.skip_ws()?;
                    if self.peek() == Some('}') && self.d == Dialect::Json {
                        return Err((comma, "Trailing commas are not allowed".into()));
                    }
                }
                Some('}') => {
                    self.i += 1;
                    break;
                }
                None => {
                    return Err(match self.d {
                        Dialect::Json5 => (self.i, "Expecting '}' at end of object".into()),
                        _ => (start, "Unterminated object".into()),
                    })
                }
                _ => return Err(self.unexpected()),
            }
        }
        let trailing = self.take_comments();
        self.depth -= 1;
        Ok(Value::Obj(members, trailing))
    }

    fn array(&mut self) -> R<Value> {
        let start = self.i;
        self.enter()?;
        self.i += 1;
        let mut items = Vec::new();
        loop {
            self.skip_ws()?;
            match self.peek() {
                None => {
                    return Err(match self.d {
                        Dialect::Json5 => (self.i, "Expecting ']' at end of array".into()),
                        _ => (start, "Unterminated array".into()),
                    })
                }
                Some(']') => {
                    self.i += 1;
                    break;
                }
                Some(',') => return Err(self.unexpected()),
                _ => {}
            }
            let comments = self.take_comments();
            let v = self.value()?;
            items.push(Elem { comments, value: v });
            self.skip_ws()?;
            match self.peek() {

    }
    match std::str::from_utf8(bytes) {
        Ok(s) => Ok(s.to_string()),
        Err(e) => Err(format!("invalid UTF-8: {}", e)),
    }
}

fn base_options(m: &Matches) -> Options {
    let mut o = Options::default();
    if let Some(n) = m.value("line-width") {
        o.line_width = n.parse().unwrap_or(80);
    }
    if let Some(n) = m.value("prose-width") {
        o.prose_width = n.parse().unwrap_or(72);
    }
    if let Some(n) = m.value("indent-width") {
        o.indent_width = n.parse().unwrap_or(2);
    }
    o.canonical = m.flag("canonical");
    o.preserve_footnotes = m.flag("preserve-footnotes");
    o.compact = m.flag("compact");
    o.skip_embedded = m.flag("skip-embedded-formatters");
    o.diagnostics = m.flag("diagnostics");
    o
}

/// Apply config and CLI overrides to produce the effective options for one file.
pub fn effective_options(m: &Matches, cfg: Option<&config::Config>, file: &Path) -> Options {
    let mut o = base_options(m);
    if let Some(c) = cfg {
        c.apply(&mut o, file);
    }
    if m.flag("compact") {
        o.compact = true;
    }
    if let Some(w) = m.value("wrap") {
        if let Some(w) = crate::options::parse_wrap(w) {
            o.wrap = w;
        }
    }
    if let Some(t) = m.value("table-widths") {
        o.table_widths = if t == "preserve" { TableWidths::Preserve } else { TableWidths::Fit };
    }
    o
}

fn print_diag(path: &str, d: &Diagnostic, kind: &str) -> String {
    format!("{}:{}:{}: {}: {}\n", path, d.line, d.col, kind, d.msg)
}

fn run_stdin(m: &Matches, path: &str) -> i32 {
    let kind = match detect_kind(path) {
        Some(k) => k,
        None => {
            eprint!("{}:1:1: error: unsupported file type\n", path);
            return 1;
        }
    };
    let cfg = match load_config_for(m, Path::new(path)) {
        Ok(c) => c,
        Err((p, msg)) => {
            eprint!("{}:1:1: error: {}\n", p, msg);
            return 1;
        }
    };
    let mut bytes = Vec::new();
    let _ = std::io::stdin().read_to_end(&mut bytes);
    let text = match decode(&bytes) {
        Ok(t) => t,
        Err(e) => {
            eprint!("{}:1:1: error: {}\n", path, e);
            return 1;
        }
    };
    let opts = effective_options(m, cfg.as_ref(), Path::new(path));
    match format_text(kind, &text, &opts) {
        Ok(out) => {
            let mut err = String::new();
            if opts.diagnostics {
                for n in &out.notes {
                    err.push_str(&print_diag(path, n, "note"));
                }
            }
            eprint!("{}", err);
            let mut so = std::io::stdout();
            let _ = so.write_all(out.text.as_bytes());
            let _ = so.flush();
            0
        }
        Err(d) => {
            eprint!("{}", print_diag(path, &d, "error"));
            1
        }
    }
}

type ConfigResult = Result<Option<config::Config>, (String, String)>;

fn load_config_for(m: &Matches, file: &Path) -> ConfigResult {
    if let Some(p) = m.value("config") {
        return config::load_explicit(p).map(Some);
    }
    config::discover(file)
}

pub fn run_format(m: &Matches) -> i32 {
    if let Some(p) = m.value("stdin-file-path") {
        if !m.positionals.is_empty() {
            eprint!("error: --stdin-file-path cannot be used with PATHS\n");
            return 2;
        }
        if m.flag("check") || m.flag("diff") {
            eprint!("error: --stdin-file-path cannot be used with --check or --diff\n");
            return 2;
        }
        let p = p.to_string();
        return run_stdin(m, &p);
    }
    let check = m.flag("check");
    let diff_mode = m.flag("diff");
    let roots: Vec<String> = if m.positionals.is_empty() {
        vec![".".to_string()]
    } else {
        m.positionals.clone()
    };
    for r in &roots {
        if std::fs::symlink_metadata(r).is_err() && !Path::new(r).exists() {
            eprint!("{}:1:1: error: path does not exist\n", r);
            return 1;
        }
    }
    // Explicit config is loaded once up front.
    let explicit_cfg = if let Some(p) = m.value("config") {
        match config::load_explicit(p) {
            Ok(c) => Some(c),
            Err((p, msg)) => {
                eprint!("{}:1:1: error: {}\n", p, msg);
                return 1;
            }
        }
    } else {
        None
    };
    let mut files: Vec<PathBuf> = Vec::new();
    let mut seen: HashSet<PathBuf> = HashSet::new();
    let mut walker = Walker::new();
    for r in &roots {
        let p = Path::new(r);
        let list = if p.is_dir() { walker.walk(p) } else { vec![p.to_path_buf()] };
        for f in list {
            let key = std::fs::canonicalize(&f).unwrap_or_else(|_| f.clone());
            if seen.insert(key) {
                files.push(f);
            }
        }
    }

    // Configurations are resolved for every selected file before any formatting.
    let mut configs: Vec<Option<config::Config>> = Vec::new();
    {
        let mut cache: std::collections::HashMap<PathBuf, Option<config::Config>> = std::collections::HashMap::new();
        for f in &files {
            if explicit_cfg.is_some() || detect_kind(&f.to_string_lossy()).is_none() {
                configs.push(None);
                continue;
            }
            let dir = f.parent().map(|p| p.to_path_buf()).unwrap_or_default();
            if let Some(c) = cache.get(&dir) {
                configs.push(c.clone());
                continue;
            }
            match config::discover(f) {
                Ok(c) => {
                    cache.insert(dir, c.clone());
                    configs.push(c);
                }
                Err((p, msg)) => {
                    eprint!("{}:1:1: error: {}\n", p, msg);
                    return 1;
                }
            }
        }
    }
    let mut scanned = 0usize;
    let mut formatted = 0usize;
    let mut unchanged = 0usize;
    let mut skipped = 0usize;
    let mut failed = 0usize;
    // (path, is_note, text)
    let mut msgs: Vec<(String, bool, String)> = Vec::new();
    let mut stdout = std::io::stdout();
    for (fi, f) in files.iter().enumerate() {
        scanned += 1;
        let display = f.to_string_lossy().into_owned();
        let kind = match detect_kind(&display) {
            Some(k) => k,
            None => {
                skipped += 1;
                continue;
            }
        };
        let cfg: Option<&config::Config> = if let Some(c) = &explicit_cfg { Some(c) } else { configs[fi].as_ref() };
        let bytes = match std::fs::read(f) {
            Ok(b) => b,
            Err(e) => {
                failed += 1;
                msgs.push((display.clone(), false, format!("{}:1:1: error: failed to read file: {}\n", display, io_error_text(&e))));
                continue;
            }
        };
        let text = match decode(&bytes) {
            Ok(t) => t,
            Err(e) => {
                failed += 1;
                msgs.push((display.clone(), false, format!("{}:1:1: error: failed to read file: {}\n", display, e)));
                continue;
            }
        };
        let opts = effective_options(m, cfg, f);
        match format_text(kind, &text, &opts) {
            Ok(out) => {
                for n in &out.notes {
                    msgs.push((display.clone(), true, print_diag(&display, n, "note")));
                }
                if out.text == text {
                    unchanged += 1;
                } else {
                    formatted += 1;
                    if diff_mode {
                        let d = diff::unified_diff(&text, &out.text, &display, &display);
                        let _ = stdout.write_all(d.as_bytes());
                    } else if !check {
                        if let Err(e) = std::fs::write(f, out.text.as_bytes()) {
                            failed += 1;
                            formatted -= 1;
                            msgs.push((display.clone(), false, format!("{}:1:1: error: failed to write file: {}\n", display, io_error_text(&e))));
                        }
                    }
                }
            }
            Err(d) => {
                failed += 1;
                msgs.push((display.clone(), false, print_diag(&display, &d, "error")));
            }
        }
    }
    let show_notes = m.flag("diagnostics") || failed > 0;
    msgs.sort_by(|a, b| a.0.cmp(&b.0));
    let mut messages = String::new();
    for (_, is_note, text) in &msgs {
        if *is_note && !show_notes {
            continue;
        }
        messages.push_str(text);
    }
    let _ = stdout.flush();
    let summary = format!(
        "{} files scanned, {} formatted, {} unchanged, {} skipped, {} failed\n",
        scanned, formatted, unchanged, skipped, failed
    );
    if check || diff_mode {
        eprint!("{}{}", summary, messages);
    } else {
        let _ = stdout.write_all(summary.as_bytes());
        let _ = stdout.flush();
        eprint!("{}", messages);
    }
    if failed > 0 {
        return 1;
    }
    if (check || diff_mode) && formatted > 0 {
        return 1;
    }
    0
}

pub fn io_error_text(e: &std::io::Error) -> String {
    e.to_string()
}
// YAML formatting.

pub mod directive;
pub mod emit;
pub mod parser;
pub mod scalar;

use crate::format_cmd::Diagnostic;
use crate::options::Options;
use std::cell::RefCell;

thread_local! {
    /// Notes produced while formatting YAML (embedded formatter skips).
    pub static YAML_NOTES: RefCell<Vec<Diagnostic>> = const { RefCell::new(Vec::new()) };
    /// Counters from the most recent YAML emission.
    pub static LAST_STATS: RefCell<Option<(emit::Stats, usize)>> = const { RefCell::new(None) };
}

fn count_nodes(n: &parser::Node) -> usize {
    use parser::Kind;
    1 + match &n.kind {
        Kind::Map(es) => es.iter().map(|e| (if e.quirk == 0 { 1 } else { 0 }) + count_nodes(&e.value)).sum(),
        Kind::Seq(items) => items.iter().map(|i| count_nodes(&i.value)).sum(),
        Kind::FlowMap(es) | Kind::FlowSeq(es) => es
            .iter()
            .map(|e| e.key.as_ref().map(count_nodes).unwrap_or(0) + e.value.as_ref().map(count_nodes).unwrap_or(0))
            .sum(),
        _ => 0,
    }
}

/// Format a YAML stream. Unparseable input is returned unchanged.
pub fn format_yaml(src: &str, opts: &Options) -> Result<String, Diagnostic> {
    if src.is_empty() {
        return Ok(String::new());
    }
    let p = parser::Parser::new(src);
    let line_starts = p.line_starts.clone();
    let stream = match p.parse_stream() {
        Ok(s) => s,
        Err(e) => {
            if std::env::var_os("YAMARK_DEBUG").is_some() {
                let line = src[..e.pos.min(src.len())].matches('\n').count() + 1;
                eprintln!("yaml parse error at line {}: {}", line, e.msg);
            }
            return Ok(src.to_string());
        }
    };
    let dirs = directive::collect(src, &stream, &line_starts)?;
    if dirs.skip_file {
        return Ok(src.to_string());
    }
    let mut em = emit::Emitter::new(src, stream.line_kinds.clone(), line_starts, opts);
    em.off_regions = dirs.off_regions.clone();
    em.skip_lines = dirs.skip_lines.clone();
    em.md_dirs = dirs.markdown.clone();
    em.opt_dirs = dirs.options.clone();
    em.emb_dirs = dirs.embedded.clone();
    resolve_collection_dirs(src, &stream, &line_starts_of(src), &dirs, &mut em)?;
    em.emit_stream(&stream);
    if let Some(e) = em.error.take() {
        return Err(e);
    }
    YAML_NOTES.with(|n| n.borrow_mut().extend(em.notes.drain(..)));
    let stats = em.stats.clone();
    let semantic: usize = stream.docs.iter().map(|d| d.root.as_ref().map(count_nodes).unwrap_or(0)).sum();
    LAST_STATS.with(|s| *s.borrow_mut() = Some((stats, semantic)));
    if let Some(&l) = em.skip_lines.iter().find(|l| !em.used_skips.contains(l)) {
        let _ = l;
        let (el, ec) = directive::eof_pos(src);
        return Err(Diagnostic { line: el, col: ec, msg: "fmt: skip has no target".into() });
    }
    let mut out = em.out.join("\n");
    if src.ends_with('\n') {
        out.push('\n');
    }
    Ok(out)
}

fn line_starts_of(src: &str) -> Vec<usize> {
    let mut v = vec![0];
    for (i, c) in src.bytes().enumerate() {
        if c == b'\n' {
            v.push(i + 1);
        }
    }
    v
}

fn coll_key(n: &parser::Node, ls: &[usize]) -> usize {
    match &n.kind {
        parser::Kind::Seq(items) => items.first().map(|i| ls[i.line] + i.col).unwrap_or(n.start),
        _ => n.start,
    }
}

/// Places that bind a pending collection directive, in document order:
/// (line, collection key, is sequence). Every sequence item binds its sequence;
/// a mapping entry binds its collection value.
fn dir_anchors(n: &parser::Node, ls: &[usize], out: &mut Vec<(usize, usize, bool)>) {
    use parser::Kind;
    match &n.kind {
        Kind::Map(es) => {
            for e in es {
                let v = &e.value;
                if matches!(v.kind, Kind::Map(_) | Kind::Seq(_) | Kind::FlowMap(_) | Kind::FlowSeq(_)) {
                    out.push((e.line, coll_key(v, ls), matches!(v.kind, Kind::Seq(_) | Kind::FlowSeq(_))));
                }
                dir_anchors(v, ls, out);
            }
        }
        Kind::Seq(items) => {
            let k = coll_key(n, ls);
            for it in items {
                out.push((it.line, k, true));
                dir_anchors(&it.value, ls, out);
            }
        }
        Kind::FlowSeq(_) => out.push((n.line, n.start, true)),
        _ => {}
    }
}

/// Bind `fmt: table` and `fmt: compact` directives to the collections they target.
fn resolve_collection_dirs(src: &str, stream: &parser::Stream, ls: &[usize], dirs: &directive::Directives, em: &mut emit::Emitter) -> Result<(), Diagnostic> {
    use directive::Scope;
    let mut anchors = Vec::new();
    for d in &stream.docs {
        if let Some(r) = &d.root {
            dir_anchors(r, ls, &mut anchors);
        }
    }
    let eof = || directive::eof_pos(src);
    for &(line, collapse) in &dirs.tables {
        match anchors.iter().find(|a| a.2 && a.0 > line) {
            Some(a) => {
                em.table_targets.insert(a.1, collapse);
            }
            None => {
                let (l, c) = eof();
                return Err(Diagnostic { line: l, col: c, msg: "fmt: table has no target".into() });
            }
        }
    }
    for &(line, on, scope) in &dirs.compacts {
        if scope != Scope::Next {
            em.compact_scoped.push((line, on, scope));
            continue;
        }
        match anchors.iter().find(|a| a.0 > line) {
            Some(a) => {
                em.compact_override.insert(a.1, on);
            }
            None => {
                let (l, c) = eof();
                return Err(Diagnostic { line: l, col: c, msg: "fmt: compact has no target".into() });
            }
        }
    }
    Ok(())
}

pub fn format_yaml_file(text: &str, opts: &Options, notes: &mut Vec<Diagnostic>) -> Result<String, Diagnostic> {
    YAML_NOTES.with(|n| n.borrow_mut().clear());
    LAST_STATS.with(|s| *s.borrow_mut() = None);
    let r = match format_json_lines(text, opts) {
        Some(out) => Ok(out),
        None => format_yaml(text, opts),
    };
    YAML_NOTES.with(|n| notes.extend(n.borrow_mut().drain(..)));
    if opts.diagnostics {
        if let Ok(out) = &r {
            let lines = if text.is_empty() { 0 } else { text.strip_suffix('\n').unwrap_or(text).split('\n').count() };
            let (st, sem) = LAST_STATS.with(|s| s.borrow().clone()).unwrap_or_default();
            let msg = format!(
                "yaml trace: source_scans=1 parse_passes=1 source_lines={} yaml_scanned_lines={} yaml_semantic_nodes={} planned_rendered_scalars={} planned_rendered_flow_collections={} planned_rendered_block_flow_collections={} emitted_bytes={} emitted_nodes={}",
                lines, lines, sem, st.scalars, st.flows, st.block_flows, out.len(), st.emitted_nodes
            );
            notes.push(Diagnostic { line: 1, col: 1, msg });
        }
    }
    r
}

/// A stream of two or more one-line flow-mapping roots becomes a multi-document stream.
fn format_json_lines(text: &str, opts: &Options) -> Option<String> {
    let body = text.strip_suffix('\n').unwrap_or(text);
    let lines: Vec<&str> = body.split('\n').collect();
    if lines.len() < 2 {
        return None;
    }
    for l in &lines {
        let t = l.trim();
        if !t.starts_with('{') {
            return None;
        }
        let p = parser::Parser::new(t);
        let st = p.parse_stream().ok()?;
        if st.docs.len() != 1 || !st.docs[0].extra.is_empty() {
            return None;
        }
        match &st.docs[0].root {
            Some(n) if matches!(n.kind, parser::Kind::FlowMap(_)) && n.end_line == 0 => {}
            _ => return None,
        }
    }
    let mut out = String::new();
    let mut total = emit::Stats::default();
    let mut sem = 0;
    for l in &lines {
        out.push_str("---\n");
        let f = format_yaml(&format!("{}\n", l.trim_end()), opts).ok()?;
        if let Some((st, n)) = LAST_STATS.with(|s| s.borrow().clone()) {
            total.scalars += st.scalars;
            total.flows += st.flows;
            total.block_flows += st.block_flows;
            total.emitted_nodes += st.emitted_nodes;
            sem += n;
        }
        out.push_str(&f);
    }
    LAST_STATS.with(|s| *s.borrow_mut() = Some((total, sem)));
    if !text.ends_with('\n') {
        out.pop();
    }
    Some(out)
}
// yamark.toml discovery, validation and application.

use crate::options::{Options, TableWidths, Wrap};
use crate::toml::Value;
use std::path::{Path, PathBuf};

#[derive(Clone, Debug)]
pub enum TemplateLayer {
    Replace(Vec<(String, String)>),
    Add(Vec<(String, String)>),
}

#[derive(Clone, Debug, Default)]
pub struct TemplateCfg {
    pub replace: Option<Vec<(String, String)>>,
    pub add: Vec<(String, String)>,
}

#[derive(Clone, Debug)]
pub enum FormatterCfg {
    Builtin(String),
    Custom { command: Vec<String>, path_suffix: String },
}

#[derive(Clone, Debug, Default)]
pub struct Config {
    pub dir: PathBuf,
    pub wrap: Option<Wrap>,
    pub table_widths: Option<TableWidths>,
    pub compact: Option<bool>,
    pub hr: Option<String>,
    pub template: TemplateCfg,
    pub embedded: Vec<(String, FormatterCfg)>,
    pub paths: Vec<(String, Option<TemplateCfg>, Option<TemplateCfg>)>,
}

fn apply_template(base: &mut Vec<(String, String)>, t: &TemplateCfg) {
    if let Some(r) = &t.replace {
        *base = r.clone();
    }
    base.extend(t.add.iter().cloned());
}

impl Config {
    pub fn apply(&self, o: &mut Options, file: &Path) {
        if let Some(w) = self.wrap {
            o.wrap = w;
        }
        if let Some(t) = self.table_widths {
            o.table_widths = t;
        }
        if let Some(c) = self.compact {
            o.compact = c;
        }
        if let Some(h) = &self.hr {
            o.hr_marker = h.clone();
        }
        apply_template(&mut o.templates.pairs, &self.template);
        apply_template(&mut o.embedded_md_templates.pairs, &self.template);
        // Path layers from shallowest to deepest.
        let abs = std::fs::canonicalize(file).unwrap_or_else(|_| {
            let p = if file.is_absolute() { file.to_path_buf() } else { std::env::current_dir().unwrap_or_default().join(file) };
            p
        });
        let rel = abs.strip_prefix(&self.dir).map(|p| p.to_path_buf()).unwrap_or_default();
        let mut layers: Vec<&(String, Option<TemplateCfg>, Option<TemplateCfg>)> = self
            .paths
            .iter()
            .filter(|(k, _, _)| {
                let kp = Path::new(k.trim_end_matches('/'));
                rel.starts_with(kp)
            })
            .collect();
        layers.sort_by_key(|(k, _, _)| Path::new(k).components().count());
        for (_, t, em) in layers {
            if let Some(t) = t {
                apply_template(&mut o.templates.pairs, t);
                apply_template(&mut o.embedded_md_templates.pairs, t);
            }
            if let Some(em) = em {
                apply_template(&mut o.embedded_md_templates.pairs, em);
            }
        }
    }
}

type CfgErr = (String, String);

fn parse_delims(v: &Value, name: &str) -> Result<Vec<(String, String)>, String> {
    let arr = match v {
        Value::Array(a) => a,
        _ => return Err(format!("{} must be an array", name)),
    };
    let mut out = Vec::new();
    for item in arr {
        let t = match item {
            Value::Table(t) => t,
            _ => return Err(format!("{} entries must be tables", name)),
        };
        for (k, _) in t {
            if k != "open" && k != "close" {
                return Err(format!("unknown {} key: {}", name, k));
            }
        }
        let open = match item.get("open") {
            Some(Value::Str(s)) => s.clone(),
            Some(_) => return Err(format!("{}.open must be a string", name)),
            None => return Err(format!("{}.open is required", name)),
        };
        let close = match item.get("close") {
            Some(Value::Str(s)) => s.clone(),
            Some(_) => return Err(format!("{}.close must be a string", name)),
            None => return Err(format!("{}.close is required", name)),
        };
        if open.is_empty() {
            return Err(format!("{}.open must not be empty", name));
        }
        if close.is_empty() {
            return Err(format!("{}.close must not be empty", name));
        }
        out.push((open, close));
    }
    Ok(out)
}

fn parse_template(v: &Value, prefix: &str) -> Result<TemplateCfg, String> {
    let t = match v {
        Value::Table(t) => t,
        _ => return Err(format!("{} config must be a table", prefix)),
    };
    let mut cfg = TemplateCfg::default();
    for (k, val) in t {
        match k.as_str() {
            "add_delimiters" => cfg.add = parse_delims(val, &format!("{}.add_delimiters", prefix))?,
            "replace_delimiters" => cfg.replace = Some(parse_delims(val, &format!("{}.replace_delimiters", prefix))?),
            _ => return Err(format!("unknown template config key: {}.{}", prefix, k)),
        }
    }
    Ok(cfg)
}

const SHORTHANDS: &[&str] = &[
    "ruff", "air", "mdformat", "prettier-json", "prettier-jsonc", "prettier-json5", "prettier-graphql", "prettier-css", "prettier-scss", "prettier-less", "prettier-postcss", "prettier-html", "prettier-js", "prettier-jsx", "prettier-ts", "prettier-tsx",
];

fn parse_config(text: &str, dir: &Path) -> Result<Config, String> {
    let root = match crate::toml::parse(text) {
        Ok(v) => v,
        Err(e) => {
            let line_text = text.lines().nth(e.line.saturating_sub(1)).unwrap_or("");
            let caret = format!("{}{}", " ".repeat(e.col.saturating_sub(1)), "^".repeat(e.span.max(1)));
            let msg = e.msg.replace("\\n", "\n");
            let w = e.line.to_string().len();
            return Err(format!(
                "invalid yamark.toml: TOML parse error at line {}, column {}\n{} |\n{} | {}\n{} | {}\n{}\n",
                e.line,
                e.col,
                " ".repeat(w),
                e.line,
                line_text,
                " ".repeat(w),
                caret,
                msg
            ));
        }
    };
    let mut cfg = Config { dir: dir.to_path_buf(), ..Default::default() };
    let top = match &root {
        Value::Table(t) => t,
        _ => return Err("invalid yamark.toml".into()),
    };
    for (k, v) in top {
        match k.as_str() {
            "format" => {
                let t = match v {
                    Value::Table(t) => t,
                    _ => return Err("format config must be a table".into()),
                };
                for (fk, fv) in t {
                    match fk.as_str() {
                        "wrap" => match fv {
                            Value::Str(s) => match crate::options::parse_wrap(s) {
                                Some(w) => cfg.wrap = Some(w),
                                None => return Err("format.wrap must be none, paragraph, sentence, a positive integer, or sentence:<positive integer>".into()),
                            },
                            _ => return Err("format.wrap must be a string".into()),
                        },
                        "table_widths" => match fv {
                            Value::Str(s) if s == "fit" => cfg.table_widths = Some(TableWidths::Fit),
                            Value::Str(s) if s == "preserve" => cfg.table_widths = Some(TableWidths::Preserve),
                            _ => return Err("format.table_widths must be fit or preserve".into()),
                        },
                        "compact" => match fv {
                            Value::Bool(b) => cfg.compact = Some(*b),
                            _ => return Err("format.compact must be a boolean".into()),
                        },
                        "markdown_horizontal_rule" => match fv {
                            Value::Str(s) if s == "---" || s == "***" => cfg.hr = Some(s.clone()),
                            _ => return Err("format.markdown_horizontal_rule must be \"---\" or \"***\"".into()),
                        },
                        _ => return Err(format!("unknown format config key: format.{}", fk)),
                    }
                }
            }
            "template" => cfg.template = parse_template(v, "template")?,
            "embedded" => {
                let t = match v {
                    Value::Table(t) => t,
                    _ => return Err("embedded config must be a table".into()),
                };
                for (name, ev) in t {
                    if name.is_empty() || name.trim() != name {
                        return Err("embedded formatter names must be non-empty and trimmed".into());
                    }
                    if matches!(name.as_str(), "skip" | "skip file" | "off" | "on" | "table") {
                        return Err(format!("reserved fmt directive name: {}", name));
                    }
                    let et = match ev {
                        Value::Table(t) => t,
                        _ => return Err(format!("embedded.{} must be a table", name)),
                    };
                    let f = match ev.get("formatter") {
                        Some(f) => f,
                        None => return Err("embedded formatter entries must contain formatter".into()),
                    };
                    for (ek, _) in et {
                        if ek != "formatter" {
                            return Err(format!("unknown embedded config key: embedded.{}.{}", name, ek));
                        }
                    }
                    let fc = match f {
                        Value::Str(s) => {
                            if !SHORTHANDS.contains(&s.as_str()) {
                                return Err(format!("unknown embedded formatter shorthand: {}", s));
                            }
                            FormatterCfg::Builtin(s.clone())
                        }
                        Value::Table(ft) => {
                            for (fk, _) in ft {
                                if fk != "command" && fk != "path_suffix" {
                                    return Err(format!("unknown embedded formatter key: {}", fk));
                                }
                            }
                            let command: Vec<String> = match f.get("command") {
                                Some(Value::Array(a)) => {
                                    let mut v = Vec::new();
                                    for x in a {
                                        match x {
                                            Value::Str(s) => v.push(s.clone()),
                                            _ => return Err("embedded formatter command must be an array of strings".into()),

        }
        Err(message) => {
            eprintln!("error: {message}");
            ExitCode::from(1)
        }
    }
}

fn setup_git_filter(
    repo: Option<PathBuf>,
    yamark: Option<PathBuf>,
    width: usize,
    paths: Vec<PathBuf>,
) -> Result<String, String> {
    let (repo_root, attributes_path) = git_filter_repo_paths(repo)?;
    configure_git_filter(&repo_root, yamark, width)?;

    let patterns = git_filter_attribute_patterns(&repo_root, paths)?;
    let added = append_missing_attribute_lines(&attributes_path, &patterns)?;
    Ok(format!(
        "Configured yamark Git filter in {}\nUpdated {} with {added} new attribute pattern(s)\n\nNext step:\n  git add --renormalize .\n\nUndo:\n  Temporarily stage one file exactly as it appears in the working tree:\n    git -c filter.yamark-md.clean=cat add <path>\n  Permanently remove this local setup:\n    yamark git-filter teardown\n\nPer-file control:\n  Add later Git attribute lines to .git/info/attributes or .gitattributes:\n    NEWS.md -filter\n  Then use the normal formatter for that file, for example:\n    yamark format --wrap {width} NEWS.md\n  Use <!-- fmt: skip file --> inside a Markdown file to leave its contents untouched.",
        repo_root.display(),
        attributes_path.display(),
    ))
}

fn adopt_git_filter(
    repo: Option<PathBuf>,
    yamark: Option<PathBuf>,
    width: usize,
    paths: Vec<PathBuf>,
) -> Result<String, String> {
    let (repo_root, info_attributes_path) = git_filter_repo_paths(repo)?;
    ensure_clean_worktree(&repo_root)?;
    ensure_no_local_yamark_filter_setup(&repo_root, &info_attributes_path)?;

    let attributes_path = repo_root.join(".gitattributes");
    let previous_attributes = read_optional_file(&attributes_path)?;
    let result = adopt_git_filter_inner(&repo_root, yamark, width, paths, &attributes_path);
    if let Err(err) = result {
        let rollback = rollback_adopt(&repo_root, &attributes_path, previous_attributes);
        return match rollback {
            Ok(()) => Err(format!("{err}\nRolled back yamark Git filter adoption.")),
            Err(rollback_err) => Err(format!(
                "{err}\nRollback failed: {rollback_err}\nReview the repository before continuing."
            )),
        };
    }
    result
}

fn adopt_git_filter_inner(
    repo_root: &Path,
    yamark: Option<PathBuf>,
    width: usize,
    paths: Vec<PathBuf>,
    attributes_path: &Path,
) -> Result<String, String> {
    configure_git_filter(repo_root, yamark, width)?;
    let patterns = git_filter_attribute_patterns(repo_root, paths)?;
    let added = append_missing_attribute_lines(attributes_path, &patterns)?;
    let targets = tracked_yamark_filter_paths(repo_root)?;
    if targets.is_empty() {
        return Err("no tracked Markdown files match filter=yamark-md".to_owned());
    }

    run_git_os(
        repo_root,
        &[
            OsString::from("add"),
            OsString::from("--"),
            OsString::from(".gitattributes"),
        ],
    )?;
    run_git_with_paths(repo_root, &["add", "--renormalize", "--"], &targets)?;
    verify_index_roundtrip(repo_root, &targets, width)?;
    write_smudged_worktree(repo_root, &targets)?;
    ensure_no_unstaged_changes(repo_root)?;

    Ok(format!(
        "Adopted yamark Git filter in {}\nUpdated .gitattributes with {added} new attribute pattern(s)\nStaged .gitattributes and {} normalized Markdown file(s).\n\nReview and commit with:\n  git diff --cached\n  git commit -m \"Normalize Markdown with yamark Git filter\"",
        repo_root.display(),
        targets.len(),
    ))
}

fn join_git_filter(
    repo: Option<PathBuf>,
    yamark: Option<PathBuf>,
    width: usize,
) -> Result<String, String> {
    let (repo_root, _) = git_filter_repo_paths(repo)?;
    ensure_clean_worktree(&repo_root)?;
    ensure_not_behind_upstream(&repo_root)?;
    ensure_shared_yamark_attributes(&repo_root)?;
    configure_git_filter(&repo_root, yamark, width)?;

    let targets = tracked_yamark_filter_paths(&repo_root)?;
    if targets.is_empty() {
        return Err("no tracked Markdown files match filter=yamark-md".to_owned());
    }
    verify_head_roundtrip(&repo_root, &targets, width)?;
    write_smudged_worktree(&repo_root, &targets)?;
    ensure_clean_worktree(&repo_root)?;

    Ok(format!(
        "Joined yamark Git filter in {}\nConfigured local filter driver and checked {} committed Markdown file(s).",
        repo_root.display(),
        targets.len(),
    ))
}

fn check_git_filter(repo: Option<PathBuf>, width: usize) -> Result<String, String> {
    let (repo_root, _) = git_filter_repo_paths(repo)?;
    ensure_shared_yamark_attributes(&repo_root)?;
    let targets = tracked_yamark_filter_paths(&repo_root)?;
    if targets.is_empty() {
        return Err("no tracked Markdown files match filter=yamark-md".to_owned());
    }
    verify_head_roundtrip(&repo_root, &targets, width)?;
    Ok(format!(
        "yamark Git filter check passed for {} Markdown file(s).",
        targets.len()
    ))
}

fn teardown_git_filter(repo: Option<PathBuf>) -> Result<String, String> {
    let (repo_root, attributes_path) = git_filter_repo_paths(repo)?;
    let unset = unset_git_filter_config(&repo_root)?;
    let removed = remove_yamark_filter_attribute_lines(&attributes_path)?;
    Ok(format!(
        "Removed yamark Git filter setup from {}\nUnset {unset} local Git config value(s)\nRemoved {removed} yamark attribute pattern(s) from {}\n\nTracked files keep their current index content until staged again. Run:\n  git add --renormalize .\nif you want to restage them without the filter.",
        repo_root.display(),
        attributes_path.display(),
    ))
}

#[derive(Clone, Copy)]
enum BlobSource {
    Head,
    Index,
}

impl BlobSource {
    fn spec(self, path: &Path) -> OsString {
        let mut spec = OsString::from(match self {
            Self::Head => "HEAD:",
            Self::Index => ":",
        });
        spec.push(path);
        spec
    }
}

fn configure_git_filter(
    repo_root: &Path,
    yamark: Option<PathBuf>,
    width: usize,
) -> Result<(), String> {
    let yamark = match yamark {
        Some(path) => path,
        None => env::current_exe()
            .map_err(|err| format!("failed to locate current yamark executable: {err}"))?,
    };
    let yamark = shell_quote_path(&yamark)?;

    run_git_config(
        repo_root,
        "filter.yamark-md.clean",
        &format!("{yamark} git-filter clean --stdin-filename %f"),
    )?;
    run_git_config(
        repo_root,
        "filter.yamark-md.smudge",
        &format!(
            "{yamark} git-filter smudge --stdin-filename %f --markdown-wrap-at-column {width}"
        ),
    )?;
    run_git_config(repo_root, "filter.yamark-md.required", "true")?;
    run_git_config(repo_root, "merge.renormalize", "true")
}

fn ensure_clean_worktree(repo_root: &Path) -> Result<(), String> {
    let status = git_stdout(repo_root, ["status", "--porcelain"])?;
    if status.is_empty() {
        Ok(())
    } else {
        Err(format!(
            "working tree is not clean; commit or stash changes first\n{status}"
        ))
    }
}

fn ensure_no_unstaged_changes(repo_root: &Path) -> Result<(), String> {
    let diff = git_stdout(repo_root, ["diff", "--name-only"])?;
    if diff.is_empty() {
        Ok(())
    } else {
        Err(format!(
            "checkout form is not clean after smudge\nunstaged files:\n{diff}"
        ))
    }
}

fn ensure_no_local_yamark_filter_setup(
    repo_root: &Path,
    info_attributes_path: &Path,
) -> Result<(), String> {
    for key in [
        "filter.yamark-md.clean",
        "filter.yamark-md.smudge",
        "filter.yamark-md.required",
        "merge.renormalize",
    ] {
        if local_git_config_count(repo_root, key)? > 0 {
            return Err(format!(
                "existing local Git filter config {key} is set; run yamark git-filter teardown first"
            ));
        }
    }
    let local_attribute_lines = count_yamark_filter_attribute_lines(info_attributes_path)?;
    if local_attribute_lines > 0 {
        return Err(format!(
            "{} already contains yamark filter attributes; run yamark git-filter teardown first",
            info_attributes_path.display()
        ));
    }
    Ok(())
}

fn ensure_not_behind_upstream(repo_root: &Path) -> Result<(), String> {
    let upstream = ProcessCommand::new("git")
        .arg("-C")
        .arg(repo_root)
        .arg("rev-parse")
        .arg("--abbrev-ref")
        .arg("--symbolic-full-name")
        .arg("@{upstream}")
        .output()
        .map_err(|err| format!("failed to run git rev-parse: {err}"))?;
    if !upstream.status.success() {
        return Ok(());
    }

    let behind = git_stdout(repo_root, ["rev-list", "--count", "HEAD..@{upstream}"])?;
    let behind = behind
        .trim()
        .parse::<usize>()
        .map_err(|err| format!("git rev-list output was not a count: {err}"))?;
    if behind > 0 {
        return Err("branch is behind upstream. Run git pull --ff-only first, then run yamark git-filter join.".to_owned());
    }
    Ok(())
}

fn ensure_shared_yamark_attributes(repo_root: &Path) -> Result<(), String> {
    let attributes_path = repo_root.join(".gitattributes");
    let attributes = fs::read_to_string(&attributes_path).map_err(|err| {
        format!(
            "{}: failed to read shared Git attributes: {err}",
            attributes_path.display()
        )
    })?;
    if attributes.lines().any(line_has_yamark_filter_attribute) {
        Ok(())
    } else {
        Err(format!(
            "{} does not contain filter=yamark-md; run yamark git-filter adopt in the maintainer checkout first",
            attributes_path.display()
        ))
    }
}

fn tracked_yamark_filter_paths(repo_root: &Path) -> Result<Vec<PathBuf>, String> {
    // NUL records contain native filename bytes, not UTF-8 text or Git's
    // presentation quoting. Each check-attr response is path, name, then value.
    let tracked = git_stdout_bytes(repo_root, ["ls-files", "-z"])?;
    let mut paths = Vec::new();
    for path in tracked
        .split(|byte| *byte == 0)
        .filter(|path| !path.is_empty())
    {
        #[cfg(unix)]
        let path = {
            use std::os::unix::ffi::OsStrExt;
            PathBuf::from(std::ffi::OsStr::from_bytes(path))
        };
        #[cfg(not(unix))]
        let path = PathBuf::from(
            std::str::from_utf8(path).map_err(|err| format!("git path was not UTF-8: {err}"))?,
        );
        if crate::core::document::FileKind::for_path(&path)
            != crate::core::document::FileKind::Markdown
        {
            continue;
        }
        let output = git_stdout_bytes(
            repo_root,
            [
                OsString::from("check-attr"),
                OsString::from("-z"),
                OsString::from("filter"),
                OsString::from("--"),
                path.as_os_str().to_owned(),
            ],
        )?;
        if output.split(|byte| *byte == 0).nth(2) == Some(b"yamark-md") {
            paths.push(path);
        }
    }
    Ok(paths)
}

fn verify_head_roundtrip(repo_root: &Path, paths: &[PathBuf], width: usize) -> Result<(), String> {
    verify_roundtrip(repo_root, paths, BlobSource::Head, width)
}

fn verify_index_roundtrip(repo_root: &Path, paths: &[PathBuf], width: usize) -> Result<(), String> {
    verify_roundtrip(repo_root, paths, BlobSource::Index, width)
}

fn verify_roundtrip(
    repo_root: &Path,
    paths: &[PathBuf],
    source: BlobSource,
    width: usize,
) -> Result<(), String> {
    let mut failures = Vec::new();
    for path in paths {
        let blob = git_blob(repo_root, source, path)?;
        // Discover configuration beside the target file even when --repo
        // selects a repository outside the caller's working directory.
        let source_path = repo_root.join(path);
        let smudged =
            format_git_filter_text(&source_path, blob.clone(), MarkdownWrap::Column(width))?;
        let cleaned = format_git_filter_text(&source_path, smudged, MarkdownWrap::Sentence)?;
        if cleaned != blob {
            failures.push(format!(
                "{}: roundtrip failure: clean(smudge(blob)) != blob",
                path.display()
            ));
        }
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("\n"))
    }
}

fn write_smudged_worktree(repo_root: &Path, paths: &[PathBuf]) -> Result<(), String> {
    // Let Git apply text/eol attributes and core.autocrlf before the configured
    // smudge filter. Writing formatted blob bytes directly bypasses that step.
    for path in paths {
        let smudged = git_stdout(
            repo_root,
            [
                OsString::from("cat-file"),
                OsString::from("--filters"),
                BlobSource::Index.spec(path),
            ],
        )?;
        let worktree_path = repo_root.join(path);
        fs::write(&worktree_path, smudged).map_err(|err| {
            format!(
                "{}: failed to write smudged working-tree file: {err}",
                worktree_path.display()
            )
        })?;
    }
    // Refresh Git's cached file metadata as part of checkout. A plain write can
    // leave a CRLF file marked dirty even when its cleaned blob is unchanged.
    run_git_with_paths(
        repo_root,
        &["checkout-index", "--force", "--index", "--"],
        paths,
    )
}

fn git_blob(repo_root: &Path, source: BlobSource, path: &Path) -> Result<String, String> {
    git_stdout(repo_root, [OsString::from("show"), source.spec(path)])
}

