            _ => {
                if self.peek() == Some(',') {
                    return (self.i, "Unexpected comma".into());
                }
                (self.i, "Unexpected token".into())
            }
        }
    }

    fn value(&mut self) -> R<Value> {
        self.skip_ws()?;
        let c = match self.peek() {
            Some(c) => c,
            None => return Err((self.i, "expected a JSON value".into())),
