                    ml_end = Some(j);
                    break;
                }
                j += 1;
            }
            if let Some(e) = ml_end {
                strings.push(StrLit {
                    start: i,
                    quote_start: i,
                    content_start,
                    content_end: e,
                    end: e + 1,
                    triple: false,
                    raw: false,
                    bytes: false,
                    fstring: false,
                    starts_nl: b.get(content_start) == Some(&b'\n'),
                    ml: true,
                });
                i = b[e..].iter().position(|&x| x == b'\n').map(|p| e + p).unwrap_or(b.len());
                continue;
            }
            let mut j = content_start;
            let mut close = None;
            while j < le {
                if b[j] == b'\\' {
                    j += 2;
                    continue;
                }
                if b[j] == q {
                    close = Some(j);
                    break;
                }
                j += 1;
            }
            match close {
                Some(e) => {
                    strings.push(StrLit {
                        start: i,
                        quote_start: i,
                        content_start,
                        content_end: e,
                        end: e + 1,
                        triple: false,
                        raw: false,
                        bytes: false,
                        fstring: false,
                        starts_nl: false,
                        ml: false,
                    });
                    i = e + 1;
                }
                None => i += 1,
            }
            continue;
        }
        i += 1;
    }
    Tokens { strings, comments }
}

struct Lines {
    starts: Vec<usize>,
}

impl Lines {
    fn new(src: &str) -> Self {
        let mut starts = vec![0];
        for (i, c) in src.bytes().enumerate() {
            if c == b'\n' {
                starts.push(i + 1);
            }
        }
        Lines { starts }
    }
    fn line_of(&self, pos: usize) -> usize {
        match self.starts.binary_search(&pos) {
            Ok(i) => i,
            Err(i) => i - 1,
        }
    }
}

fn line_end(src: &str, pos: usize) -> usize {
fn line_end(src: &str, pos: usize) -> usize {
    match src[pos..].find('\n') {
        Some(p) => pos + p,
        None => src.len(),
    }
}

/// Own-line comment info: (line index, indent bytes, comment text from '#').
#[derive(Debug, Clone)]
struct OwnComment {
    line: usize,
    indent: String,
    text: String,
}

enum Directive {
    Markdown(Options),
    Embedded(String),
    Skip,
    SkipFile,
    Off,
    On,
    Other,
}

fn parse_directive(text: &str, base: &Options) -> Option<Result<Directive, String>> {
    let t = text.trim_start_matches('#').trim();
    let d = t.strip_prefix("fmt:")?.trim();
    let words: Vec<&str> = d.split_whitespace().collect();
    if words.is_empty() {
        return Some(Err("empty fmt directive".into()));
    }
    match words[0] {
        "skip" => {
            if words.len() > 1 && (words[1] == "file" || words[1] == "scope=file") {
                return Some(Ok(Directive::SkipFile));
            }
            return Some(Ok(Directive::Skip));
        }
        "off" => return Some(Ok(Directive::Off)),
        "on" => return Some(Ok(Directive::On)),
        "markdown" | "md" => {
            let mut o = base.clone();
            for w in &words[1..] {
                if let Some(v) = w.strip_prefix("wrap=") {
                    if let Some(wr) = crate::options::parse_wrap(v) {
                        o.wrap = wr;
                    }
                } else if *w == "canonical" || *w == "canonical=true" {
                    o.canonical = true;
