fn shrink_wrap(o: &Options, indent: usize) -> Options {
    let mut o = o.clone();
    o.wrap = match o.wrap {
        Wrap::Column(n) => Wrap::Column(n.saturating_sub(indent).max(1)),
        Wrap::Sentence(Some(n)) => Wrap::Sentence(Some(n.saturating_sub(indent).max(1))),
        w => w,
    };
    o
}

