    static STRUCT_RECOVERY: std::cell::Cell<Option<usize>> = const { std::cell::Cell::new(None) };
}

fn note_struct_recovery(line: usize) {
    STRUCT_RECOVERY.with(|r| r.set(Some(r.get().map_or(line, |l| l.min(line)))));
}

