fn is_md_punct(c: char) -> bool {
    c.is_ascii_punctuation() || (!c.is_alphanumeric() && !c.is_whitespace() && c as u32 > 127)
}

/// Rewrite `_`-delimited emphasis as `*` (canonical spelling), using the CommonMark
/// delimiter algorithm. Code spans, math, raw HTML and templates are left alone.
pub fn canonicalize(text: &str, templates: &TemplateDelims) -> String {
    let mut chars: Vec<char> = text.chars().collect();
    let n = chars.len();
    // Protected ranges.
    let mut protected = vec![false; n];
    let mut i = 0;
    while i < n {
        let c = chars[i];
        if c == '\\' {
            i += 2;
            continue;
        }
        let end = if c == '`' {
            code_span_end(&chars, i)
        } else if c == '$' {
            math_end(&chars, i)
        } else if c == '<' {
            autolink_end(&chars, i).or_else(|| html_tag_at(&chars, i).map(|t| t.0))
        } else if c == '{' {
            template_end(&chars, i, templates)
        } else {
            None
        };
        match end {
            Some(e) => {
                for p in protected.iter_mut().take(e).skip(i) {
                    *p = true;
                }
                i = e;
            }
            None => i += 1,
        }
    }
    struct Delim {
        ch: char,
        start: usize,
        len: usize,
        orig_len: usize,
        can_open: bool,
        can_close: bool,
        active: bool,
    }
    let mut delims: Vec<Delim> = Vec::new();
    let mut i = 0;
    while i < n {
        if protected[i] {
            i += 1;
            continue;
        }
        let c = chars[i];
        if c == '\\' {
            i += 2;
            continue;
        }
        if c == '_' || c == '*' {
            let s = i;
            while i < n && chars[i] == c && !protected[i] {
                i += 1;
            }
            let prev = if s == 0 { ' ' } else { chars[s - 1] };
            let next = if i >= n { ' ' } else { chars[i] };
            let lf = !next.is_whitespace() && (!is_md_punct(next) || prev.is_whitespace() || is_md_punct(prev));
            let rf = !prev.is_whitespace() && (!is_md_punct(prev) || next.is_whitespace() || is_md_punct(next));
            let (co, cc) = if c == '_' {
                (lf && (!rf || is_md_punct(prev)), rf && (!lf || is_md_punct(next)))
            } else {
                (lf, rf)
            };
            delims.push(Delim { ch: c, start: s, len: i - s, orig_len: i - s, can_open: co, can_close: cc, active: true });
            continue;
        }
        i += 1;
    }
    // Pairs of (opener char positions, closer char positions) to rewrite.
    let mut rewrite: Vec<usize> = Vec::new();
    let mut ci = 0;
    while ci < delims.len() {
        if !delims[ci].active || !delims[ci].can_close || delims[ci].len == 0 {
            ci += 1;
            continue;
        }
        let mut found = None;
        let mut oi = ci;
        while oi > 0 {
            oi -= 1;
            let o = &delims[oi];
            let c = &delims[ci];
            if !o.active || o.len == 0 || o.ch != c.ch || !o.can_open {
                continue;
            }
            if (o.can_close || c.can_open) && (o.orig_len + c.orig_len) % 3 == 0 && !(o.orig_len % 3 == 0 && c.orig_len % 3 == 0) {
                continue;
            }
            found = Some(oi);
            break;
        }
        match found {
            Some(oi) => {
                let use_n = if delims[oi].len >= 2 && delims[ci].len >= 2 { 2 } else { 1 };
                // Opener: consume from its end; closer: from its start.
                let o_end = delims[oi].start + delims[oi].len;
                let c_start = delims[ci].start;
                if delims[oi].ch == '_' {
                    for k in 0..use_n {
                        rewrite.push(o_end - 1 - k);
                        rewrite.push(c_start + k);
                    }
                }
                delims[oi].len -= use_n;
                delims[ci].len -= use_n;
                delims[ci].start += use_n;
                for d in delims.iter_mut().take(ci).skip(oi + 1) {
                    d.active = false;
                }
                if delims[oi].len == 0 {
                    delims[oi].active = false;
                }
                if delims[ci].len == 0 {
                    ci += 1;
                }
            }
            None => {
                ci += 1;
            }
        }
    }
    for p in rewrite {
        chars[p] = '*';
    }
    chars.into_iter().collect()
}
    /// Walk `root` (a directory), returning files in traversal order.
    pub fn walk(&mut self, root: &Path) -> Vec<PathBuf> {
        let mut out = Vec::new();
        self.stack.clear();
        // Ancestors of the root contribute ignore rules.
        let abs = fs::canonicalize(root).unwrap_or_else(|_| root.to_path_buf());
        let mut ancestors: Vec<PathBuf> = abs.ancestors().skip(1).map(|p| p.to_path_buf()).collect();
        ancestors.reverse();
        let mut parents = Vec::new();
        for a in ancestors {
            parents.push(load_dir(&a));
        }
        // Use absolute paths for matching ancestors; we match with absolute paths throughout.
        self.stack = parents;
        if let Some(g) = &self.global {
            self.global_parsed = Some(parse_ignore(g, Path::new("")));
        }
        self.walk_dir(root, &abs, &mut out);
        out
    }

    fn walk_dir(&mut self, dir: &Path, abs_dir: &Path, out: &mut Vec<PathBuf>) {
        let d = load_dir(abs_dir);
        self.stack.push(d);
        let mut entries: Vec<(String, PathBuf, bool)> = Vec::new();
        if let Ok(rd) = fs::read_dir(dir) {
            for e in rd.flatten() {
                let name = e.file_name().to_string_lossy().into_owned();
                let ft = match e.file_type() {
                    Ok(f) => f,
                    Err(_) => continue,
                };
                if ft.is_symlink() {
                    continue;
                }
                entries.push((name, e.path(), ft.is_dir()));
            }
        }
        entries.sort_by(|a, b| a.0.as_bytes().cmp(b.0.as_bytes()));
        for (name, path, is_dir) in entries {
            if name.starts_with('.') {
                continue;
            }
            let abs_path = abs_dir.join(&name);
            if self.is_ignored_global_rel(&abs_path, is_dir) {
                continue;
            }
            if is_dir {
                self.walk_dir(&path, &abs_path, out);
            } else {
                out.push(path);
            }
        }
        self.stack.pop();
    }

    fn is_ignored_global_rel(&self, abs_path: &Path, is_dir: bool) -> bool {
        // Global patterns are matched against the path relative to the repository root.
        if self.is_ignored(abs_path, is_dir) {
            return true;
        }
        false
    }
