/// Skip `n` columns of any characters (tabs advance to the next multiple of 4).
pub fn cut_cols(s: &str, n: usize) -> String {
    let mut col = 0;
    for (i, c) in s.char_indices() {
        if col >= n {
            return s[i..].to_string();
        }
        if c == '\t' {
            let w = 4 - (col % 4);
            if col + w > n {
                let rem = col + w - n;
                return format!("{}{}", " ".repeat(rem), &s[i + 1..]);
            }
            col += w;
        } else {
            col += 1;
        }
    }
    String::new()
}

